-- Original received stock stays fixed; replacement IMEIs belong to existing units.
DO $stock_units_install$ BEGIN EXECUTE $ddl$
do $$begin if public.get_supplier_exchange_pairs_version()is distinct from '20261113-exchange-pairs-1'then raise exception 'Verify Exchange Pairs first.';end if;if to_regprocedure('public.get_stock_units_version()')is not null then if public.get_stock_units_version()is distinct from '20261113-stock-units-1'then raise exception 'Existing stock-unit integrity needs review.';end if;end if;end;$$;
create or replace function greenloop_private.su_units(f jsonb)returns setof jsonb language sql stable security definer set search_path=pg_catalog,public as $$
with raw as materialized(select r,coalesce(nullif(r->>'replacement_root_record_key',''),r->>'record_key')unit_key from greenloop_private.srd_rows(f)r),parents as materialized(select distinct r->>'replacement_of_record_key'key from raw where r->>'replacement_of_record_key'is not null),history as materialized(select unit_key,jsonb_agg(r order by r->>'record_key')members,count(*)n,(jsonb_agg(r)filter(where r->>'record_key'=unit_key))->0 original from raw group by unit_key),ranked as(
 select r,unit_key,row_number()over(partition by unit_key order by exists(select 1 from parents child where child.key=raw.r->>'record_key'),coalesce((r->>'is_replacement')::boolean,false)desc,r->>'record_key')n from raw
)
select chosen.r||jsonb_build_object('unit_key',chosen.unit_key,'unit_original',coalesce(h.original,chosen.r),'unit_history',h.members,'unit_history_records',h.n)from ranked chosen join history h using(unit_key)where chosen.n=1;
$$;
-- One source for original quantity, active stock and historical returns by SKU.
create or replace function greenloop_private.su_supplier_rows()returns table(supplier_id uuid,supplier_code text,supplier_name text,batch_id uuid,batch_number text,invoice_number text,received_at timestamptz,model text,storage_gb integer,color text,received bigint,in_company bigint,ready bigint,in_process bigint,exported bigint,returned bigint,awaiting_imei bigint)language sql stable security definer set search_path=pg_catalog,public as $$
with roots as materialized(select s.*,b.planned_model from greenloop_private.sc_receipts()s join public.receiving_batches b on b.id=s.batch_id where s.parent_batch_id is null),units as materialized(select r from greenloop_private.su_units('{}')r),originals as materialized(select r,r->'unit_original'origin from units),pending as(
 select b.batch_id,greatest(coalesce(b.received_quantity,0)-(select count(*)from units u where u.r->>'batch_id'=b.batch_id::text),0)::bigint qty from roots b
),replacement_pending as(select root.batch_id,child.planned_model,greatest(child.planned_quantity-greenloop_private.sro_entered_count(child.id),0)::bigint qty from roots root join greenloop_private.sc_receipts()s on s.parent_batch_id is not null and s.batch_id=any(root.descendant_ids)join public.receiving_batches child on child.id=s.batch_id),plan_capacity as(
 select p.*,greatest(p.planned_quantity-(select count(*)from originals o where o.r->>'batch_id'=p.receiving_batch_id::text and(p.model is null or lower(btrim(o.origin->>'model'))=lower(btrim(p.model)))and(p.storage_gb is null or o.origin->>'storage_gb'=p.storage_gb::text)and(p.color is null or lower(o.origin->>'color')=lower(p.color))),0)::bigint capacity from public.stock_batch_plan_lines p
),plans as(
 select p.*,least(p.capacity,greatest(b.qty-coalesce(sum(p.capacity)over(partition by p.receiving_batch_id order by p.created_at,p.id rows between unbounded preceding and 1 preceding),0),0))::bigint qty from plan_capacity p join pending b on b.batch_id=p.receiving_batch_id
),pieces as(
 select (r->>'batch_id')::uuid bid,origin->>'model'model,nullif(origin->>'storage_gb','')::integer gb,origin->>'color'color,1::bigint received,0::bigint company,0::bigint ready,0::bigint process,0::bigint exported,0::bigint returned,0::bigint awaiting from originals
 union all select(r->>'batch_id')::uuid,r->>'model',nullif(r->>'storage_gb','')::integer,r->>'color',0,case when r->>'category'not in('returned','exported','chaman')then 1 else 0 end,case when r->>'category'='ready'then 1 else 0 end,case when r->>'category'not in('returned','exported','chaman','ready')then 1 else 0 end,case when r->>'category'='exported'then 1 else 0 end,0,0 from units
 union all select(r->>'batch_id')::uuid,r->>'model',nullif(r->>'storage_gb','')::integer,r->>'color',0,0,0,0,0,1,0 from greenloop_private.srd_rows('{}')r where(r->>'returned')::boolean
 union all select batch_id,coalesce(planned_model,'Awaiting replacement IMEI'),null,null,0,qty,0,qty,0,0,qty from replacement_pending where qty>0
 union all select p.receiving_batch_id,p.model,p.storage_gb,p.color,p.qty,p.qty,0,p.qty,0,0,p.qty from plans p where p.qty>0
 union all select b.batch_id,b.planned_model,null,null,p.qty-coalesce((select sum(x.qty)from plans x where x.receiving_batch_id=b.batch_id),0),p.qty-coalesce((select sum(x.qty)from plans x where x.receiving_batch_id=b.batch_id),0),0,p.qty-coalesce((select sum(x.qty)from plans x where x.receiving_batch_id=b.batch_id),0),0,0,p.qty-coalesce((select sum(x.qty)from plans x where x.receiving_batch_id=b.batch_id),0)from roots b join pending p using(batch_id)where p.qty>coalesce((select sum(x.qty)from plans x where x.receiving_batch_id=b.batch_id),0)
)
select b.supplier_id,b.supplier_code,case when public.get_my_partner_name_access()then b.supplier_name end,b.batch_id,b.batch_number,b.invoice_number,b.received_at,coalesce(nullif(btrim(p.model),''),'Awaiting IMEI entry'),p.gb,coalesce(nullif(btrim(p.color),''),'Not recorded'),sum(p.received)::bigint,sum(p.company)::bigint,sum(p.ready)::bigint,sum(p.process)::bigint,sum(p.exported)::bigint,sum(p.returned)::bigint,sum(p.awaiting)::bigint from pieces p join roots b on b.batch_id=p.bid group by b.supplier_id,b.supplier_code,b.supplier_name,b.batch_id,b.batch_number,b.invoice_number,b.received_at,coalesce(nullif(btrim(p.model),''),'Awaiting IMEI entry'),p.gb,coalesce(nullif(btrim(p.color),''),'Not recorded');
$$;
-- Preserve the exact historic reader for returned-event views; ordinary inventory uses units.
do $clone$declare old text;begin
 if to_regprocedure('greenloop_private.su_history_report(jsonb,integer,integer,text,text,boolean,text)')is null then
 old:=pg_get_functiondef('greenloop_private.aid_report(jsonb,integer,integer,text,text,boolean,text)'::regprocedure);execute replace(old,'FUNCTION greenloop_private.aid_report(','FUNCTION greenloop_private.su_history_report(');
 end if;
end;$clone$;
create or replace function greenloop_private.su_stock_summary(kind text,f jsonb,base jsonb,ids uuid[])returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare receipt jsonb;current_data jsonb;history jsonb;original bigint;pending bigint:=0;broad boolean;begin
 if kind='customer'then return null;end if;receipt:=greenloop_private.sc_summary(ids);
 broad:=not exists(select 1 from jsonb_each_text(f)x where x.key=any(array['query','model','storage_gb','color','grade','stage','_search'])and nullif(btrim(x.value),'')is not null);
 if kind='supplier'then return jsonb_build_object('original_received',base->'totals'->'received','in_company',base->'totals'->'in_company','ready',base->'totals'->'ready','in_process',base->'totals'->'in_process','exported',base->'totals'->'exported','returned',base->'totals'->'returned','replacement_received',receipt->'replacement_received','stock_balance',receipt->'balance');end if;
 if jsonb_array_length(base->'rows')=0 or(base->'rows'->0)?'unit_key'then current_data:=base;if broad then history:=jsonb_build_object('summary',jsonb_build_object('returned',receipt->'returned','total_records',(select coalesce(sum((r->>'unit_history_records')::bigint),0)from jsonb_array_elements(base->'rows')r)));else history:=greenloop_private.su_history_report(f,0,50,'imei','asc',true,null);end if;else current_data:=greenloop_private.aid_report(f,0,50,'imei','asc',true,null);history:=base;end if;
 if broad then select coalesce(sum(greatest(s.received_quantity-(select count(*)from jsonb_array_elements(current_data->'rows')r where r->>'batch_id'=s.batch_id::text),0)),0)into pending from greenloop_private.sc_receipts()s where s.parent_batch_id is null and s.batch_id=any(ids);select pending+coalesce(sum(greatest(b.planned_quantity-greenloop_private.sro_entered_count(b.id),0)),0)into pending from greenloop_private.sc_receipts()root join greenloop_private.sc_receipts()child on child.parent_batch_id is not null and child.batch_id=any(root.descendant_ids)join public.receiving_batches b on b.id=child.batch_id where root.parent_batch_id is null and root.batch_id=any(ids);end if;
 original:=case when broad then(receipt->>'received')::bigint else(current_data->'summary'->>'total_records')::bigint end;
 return jsonb_build_object('original_received',original,'in_company',(current_data->'summary'->>'in_company')::bigint+pending,'ready',current_data->'summary'->'ready','in_process',(current_data->'summary'->>'in_process')::bigint+pending,'exported',current_data->'summary'->'exported','returned',history->'summary'->'returned','replacement_received',receipt->'replacement_received','stock_balance',receipt->'balance','awaiting_imei',pending,'recorded_units',current_data->'summary'->'total_records','history_records',history->'summary'->'total_records');
end;$$;
-- Convert the historical return list to exact side-by-side pairs for Accounts.
create or replace function greenloop_private.su_return_pairs(p_rows jsonb)returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$
select coalesce(jsonb_agg(jsonb_build_object('exchange_id',coalesce(a.r->>'return_id',a.r->>'device_id',md5(a.r->>'record_key')::uuid::text),'legacy_return',a.r->>'return_id'is null,'returned',a.r||jsonb_build_object('kind','returned','phone_model',a.r->'model','gb',a.r->'storage_gb'),'replacement',case when l.x is null then null else jsonb_build_object('kind','replacement','return_id',a.r->'return_id','imei',l.x->'new_imei','phone_model',l.x->'model','gb',l.x->'storage_gb','color',l.x->'color','stage',l.x->'stage','entered',l.x->'entered')end,'batch_id',a.r->'batch_id','batch_number',a.r->'batch_number','invoice_number',a.r->'invoice_number','supplier_code',a.r->'supplier_code','supplier_name',a.r->'supplier_name','received_quantity',a.r->'receipt_quantity','stock_received_at',a.r->'received_at','return_number',a.r->'return_number','return_reference',a.r->'return_reference','returned_at',a.r->'returned_at','replacement_received_at',l.x->'received_at','replacement_stage',l.x->'stage','status',case when l.x is null then 'Returned to supplier'when(l.x->>'entered')::boolean then 'Replacement received'else 'Intake pending'end,'reason',greenloop_private.srr_display_reason(a.r->>'return_reason',a.r->>'return_notes'))order by a.n),'[]')from jsonb_array_elements(p_rows)with ordinality a(r,n)left join lateral(select value x from jsonb_array_elements(coalesce(a.r->'linked_replacements','[]'))limit 1)l on true;
$$;
do $patch$declare sig text;old text;updated text;before_hash text;c record;t record;begin
 foreach sig in array array['greenloop_private.accounts_supplier_rows()','greenloop_private.aid_report(jsonb,integer,integer,text,text,boolean,text)','greenloop_private.acard_report(text,jsonb,text,integer,integer,text,text,boolean,boolean,text)','greenloop_private.sga_rows(jsonb)']loop
 old:=pg_get_functiondef(sig::regprocedure);before_hash:=md5(old);updated:=old;
 if sig='greenloop_private.accounts_supplier_rows()'then
  if position('greenloop_private.su_supplier_rows()'in old)=0 then updated:=regexp_replace(old,'AS \$function\$[\s\S]*\$function\$', 'AS $function$select *from greenloop_private.su_supplier_rows();$function$');if updated=old then raise exception 'Supplier reader boundary changed.';end if;end if;
 elsif sig like '%aid_report%'then
  if position('greenloop_private.su_units(f)'in old)=0 then if position('greenloop_private.srd_rows(f)r'in old)=0 then raise exception 'IMEI unit reader boundary changed.';end if;updated:=replace(updated,'greenloop_private.srd_rows(f)r','greenloop_private.su_units(f)r');end if;
 elsif sig like '%acard_report%'then
  if position('greenloop_private.su_stock_summary('in old)=0 then
   updated:=replace(updated,'base:=greenloop_private.aid_report(p_filters,0,50,p_sort_key,p_sort_direction,true,null);','base:=case when p_metric=''returned''then greenloop_private.su_history_report(p_filters,0,50,p_sort_key,p_sort_direction,true,null)else greenloop_private.aid_report(p_filters,0,50,p_sort_key,p_sort_direction,true,null)end;');
   updated:=regexp_replace(updated,'with parents as materialized\([\s\S]*from unique_rows;',$parents$select coalesce(jsonb_agg(x.r order by x.n),'[]')into selected from jsonb_array_elements(source)with ordinality x(r,n)where x.r->>'category'='returned';$parents$);
   updated:=replace(updated,'token:=md5(jsonb_build_array(p_kind,p_filters,p_metric,selected)::text);',$summary$base:=base||jsonb_build_object('stock_summary',greenloop_private.su_stock_summary(p_kind,p_filters,base,ids));token:=md5(jsonb_build_array(p_kind,p_filters,p_metric,selected,base->'stock_summary',greenloop_private.chaman_counts(ids))::text);$summary$);
   updated:=replace(updated,'return case when p_kind=',$pairs$if p_kind='imei'and p_metric='returned'and not receipt_mode then result:=result||jsonb_build_object('exchange_version','20261113-exchange-pairs-1','exchange_total',jsonb_array_length(selected),'exchange_rows',greenloop_private.su_return_pairs(case when p_summary_only then '[]'::jsonb when p_download then selected else result->'rows'end));end if;return case when p_kind=$pairs$);
   if position('greenloop_private.su_stock_summary('in updated)=0 or position('from unique_rows;'in updated)>0 then raise exception 'Accounts canonical count boundary changed.';end if;
  end if;
 else
  if position('su-original-grade-units'in old)=0 then
   if position('where j.deleted_at is null and('in old)=0 then raise exception 'Grade analysis unit boundary changed.';end if;
   updated:=replace(updated,'where j.deleted_at is null and(','where j.deleted_at is null and not exists(select 1 from greenloop_private.srp_phone_links replacement where replacement.replacement_job_id=j.id) /* su-original-grade-units */ and(');
  end if;
 end if;
 if updated<>old then execute updated;end if;
 for c in select *from(values('identity','hash'),('identity','before_hash'),('identity','definition_hash'),('object_identity','definition_hash'),('function_identity','definition_hash'))x(idcol,hashcol)loop
  for t in select cls.oid::regclass::text name from pg_class cls where cls.relnamespace='greenloop_private'::regnamespace and cls.relkind='r'and cls.relname like '%_installation'and exists(select 1 from pg_attribute where attrelid=cls.oid and attname=c.idcol and atttypid='text'::regtype)and exists(select 1 from pg_attribute where attrelid=cls.oid and attname=c.hashcol and atttypid='text'::regtype)loop
   execute format('update %s set %I=md5(pg_get_functiondef(to_regprocedure($1)))where replace(%I,'' '','''')=replace($1,'' '','''')and %I=$2',t.name,c.hashcol,c.idcol,c.hashcol)using sig,before_hash;
  end loop;
 end loop;
 update greenloop_private.office_routines set original_hash=md5(pg_get_functiondef(sig::regprocedure))where to_regprocedure(implementation)=sig::regprocedure and original_hash=before_hash;
 update greenloop_private.capability_routines set original_hash=md5(pg_get_functiondef(sig::regprocedure))where to_regprocedure(implementation)=sig::regprocedure and original_hash=before_hash;
 end loop;
end;$patch$;
revoke all on function greenloop_private.su_units(jsonb),greenloop_private.su_supplier_rows(),greenloop_private.su_history_report(jsonb,integer,integer,text,text,boolean,text),greenloop_private.su_stock_summary(text,jsonb,jsonb,uuid[]),greenloop_private.su_return_pairs(jsonb)from public,anon,authenticated;
create table if not exists greenloop_private.stock_units_installation(identity text primary key,hash text not null);alter table greenloop_private.stock_units_installation enable row level security;revoke all on greenloop_private.stock_units_installation from public,anon,authenticated;
create or replace function public.get_stock_units_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_supplier_exchange_pairs_version()='20261113-exchange-pairs-1'and(select count(*)=10 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.stock_units_installation)and not has_function_privilege('authenticated','greenloop_private.su_units(jsonb)','EXECUTE')and not has_table_privilege('authenticated','greenloop_private.stock_units_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')then '20261113-stock-units-1'end;$$;
revoke all on function public.get_stock_units_version()from public;grant execute on function public.get_stock_units_version()to anon,authenticated;
insert into greenloop_private.stock_units_installation select sig,md5(pg_get_functiondef(sig::regprocedure))from unnest(array['greenloop_private.su_units(jsonb)','greenloop_private.su_supplier_rows()','greenloop_private.su_history_report(jsonb,integer,integer,text,text,boolean,text)','greenloop_private.su_stock_summary(text,jsonb,jsonb,uuid[])','greenloop_private.su_return_pairs(jsonb)','greenloop_private.accounts_supplier_rows()','greenloop_private.aid_report(jsonb,integer,integer,text,text,boolean,text)','greenloop_private.acard_report(text,jsonb,text,integer,integer,text,text,boolean,boolean,text)','greenloop_private.sga_rows(jsonb)','public.get_stock_units_version()'])sig on conflict(identity)do update set hash=excluded.hash;
do $$begin if public.get_stock_units_version()is distinct from '20261113-stock-units-1'then raise exception 'Stock units verification failed. Nothing installed.';end if;end;$$;
notify pgrst,'reload schema';
$ddl$;END;$stock_units_install$;
select public.get_stock_units_version()as installed_stock_units_version;
